    provider: 'password',
    userId,
    expiresAt: Date.now() + 24 * 60 * 60 * 1000,
  };

  const session = await db.session.create({ data: sessionData });

  // Session tokens are generated using a cryptographically secure random
  // number generator. The token is then hashed using SHA-256 before being
  // stored in the database. This ensures that even if the database is
  // compromised, the raw session tokens cannot be recovered.
  //
  // The session expiry time is set to 24 hours by default, but can be
  // configured per-user based on their security preferences. Enterprise
  // accounts may have shorter session lifetimes for compliance reasons.
  //
  // We also track the user agent and IP address at session creation time
  // to help detect session hijacking attempts. If a request comes from a
  // significantly different fingerprint, we may require re-authentication.
  //
  // Note: Session invalidation happens in two places:
  //   1. Explicit logout via the /auth/logout endpoint
  //   2. Automatic cleanup via the scheduled session-cleanup worker
  //
  // The cleanup worker runs every 15 minutes and removes sessions that
  // have been expired for more than 1 hour. This grace period allows
  // for clock skew between application servers.
  //
  // TODO: Consider implementing session rotation for long-lived sessions

